'use strict';
let D=null, csrf='', syncStatus=null;
let refreshPending=false;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toDate=s=>new Date(s+'T12:00:00Z'), addDays=(s,n)=>{let d=toDate(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const nice=(s,year=false)=>s?toDate(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',...(year?{year:'numeric'}:{})}):'Not available';
const monday=s=>{const d=toDate(s),n=(d.getUTCDay()+6)%7;return addDays(s,-n)};
