const when=value=>value?new Date(value).toLocaleString('en-GB',{timeZone:'Europe/London',dateStyle:'medium',timeStyle:'short'}):'Never';
function sourceSync(key){const source=syncStatus?.sources?.[key];return [esc(when(source?.lastSuccessfulFetch)),esc(source?.lastResult==='error'?source.lastError:source?.lastResult==='retained'?'Saved data retained; refresh incomplete':source?.lastResult==='success'?'Updated':'Not fetched')];}
function renderSyncControls(){
  const button=$('#refresh-data');button.disabled=!syncStatus?.configured||!!syncStatus?.refreshing||refreshPending;
  button.textContent=syncStatus?.refreshing||refreshPending?'Refreshing…':'Refresh';
  button.title=syncStatus?.configured?'Refresh activity and recovery records':'Connect Tredict in the private server settings first';
  $('#freshness-note').textContent=(syncStatus?.refreshing?'Refresh in progress. ':syncStatus?.lastRefreshError?'Last refresh failed; saved data retained. ':'')+
    (syncStatus?.lastSuccessfulFetch?'Last successful refresh '+when(syncStatus.lastSuccessfulFetch)+'. ':syncStatus?.configured?'Tredict setup saved; no successful refresh yet. ':'Tredict is not connected. ')+
    'Latest activity '+nice(syncStatus?.latestObservation?.activities,true)+'.';
}
async function followRefresh(){
  refreshPending=true;renderSyncControls();
  try {
    for(let attempt=0;attempt<100;attempt++){
      syncStatus=await api('/api/status');renderSyncControls();
      if(!syncStatus.refreshing)break;
      await new Promise(resolve=>setTimeout(resolve,1500));
    }
    D=(await api('/api/snapshot')).snapshot;
    // Keep unsaved journal and questionnaire inputs intact while data refreshes.
    if(D&&!['journal','questions'].includes(S.view))render();
    if(syncStatus.refreshing)message('Refresh is still running. You can keep using the saved data.');
    else if(syncStatus.lastRefreshError)message(syncStatus.lastRefreshError,true);
    else message('Activity and recovery records refreshed.');
  } finally {refreshPending=false;renderSyncControls();}
}
