const logoutChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('training-auth'):null;
function lock(){D=null;checkins=[];tests=[];answers={};document.body.classList.add('locked');document.querySelector('.app')?.replaceChildren();location.replace('/login');}
if(logoutChannel) logoutChannel.onmessage=()=>lock();
async function api(path,method='GET',value) {
  const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',
    headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},
    ...(value===undefined?{}:{body:JSON.stringify(value)})});
  if(response.status===401){lock();throw Error('Your session ended. Please sign in.');}
  const data=await response.json();
  if(!response.ok) throw Error(data.error||'Unable to complete the request.');
  return data;
}
async function loadJournal(){const data=await api('/api/journal');checkins=data.checkins;tests=data.benchmarks;answers=data.questionnaire.answers;answerRevision=data.questionnaire.revision;}
async function accountBackup(){const data=await api('/api/export');download('training-backup.json',JSON.stringify(data,null,2),'application/json');}
function readablePlan(){const p=D.plan;const lines=[p.name,'Version: '+p.version,'',...Object.entries(p.rules||{}).map(([k,v])=>k.toUpperCase()+': '+v),''];for(const w of p.weeks){lines.push('WEEK '+w.week+' | '+w.start_date+' to '+w.end_date,w.focus,'');for(const e of w.days) lines.push(e.day+' — '+e.sport+' | '+e.slot_minutes+(e.max_minutes?'–'+e.max_minutes:'')+' min'+(e.optional?' | optional / conditional':''),e.description,'');if(w.optional_cycle_minutes)lines.push('Optional cycle: '+w.optional_cycle_minutes+' min, on a non-rest day.','');}download('training-plan.txt',lines.join('\n'),'text/plain;charset=utf-8');}

document.addEventListener('click',async e=>{
  try {
    const v=e.target.closest('[data-view]');if(v&&D){S.view=v.dataset.view;render();window.scrollTo({top:0,behavior:'instant'});return;}
    const range=e.target.closest('[data-range]');if(range){S.range=range.dataset.range;render();return;}
    const sport=e.target.closest('[data-sport]');if(sport){S.sport=sport.dataset.sport;render();return;}
    const week=e.target.closest('[data-week]');if(week){S.week=Number(week.dataset.week);render();return;}
    const activity=e.target.closest('[data-activity]');if(activity){showActivity(activity.dataset.activity);return;}
    const del=e.target.closest('[data-delete-checkin]');
    if(del&&confirm('Delete this check-in from your account?')){
      const row=checkins.find(x=>x.date===del.dataset.deleteCheckin);del.disabled=true;
      await api('/api/checkins/'+encodeURIComponent(row.date),'DELETE',{revision:row.revision});await loadJournal();render();return;
    }
    const dt=e.target.closest('[data-delete-test]');
    if(dt&&confirm('Delete this benchmark from your account?')){
      const row=tests.find(x=>x.id===dt.dataset.deleteTest);dt.disabled=true;
      await api('/api/benchmarks/'+encodeURIComponent(row.id),'DELETE',{revision:row.revision});await loadJournal();render();return;
    }
    if(['export-data','backup-all','export-checkins'].includes(e.target.id)) await accountBackup();
    if(e.target.id==='export-answers') download('training-answers.json',JSON.stringify({type:'questionnaire',version:D.plan.version,answers},null,2),'application/json');
    if(e.target.id==='export-plan') readablePlan();
    if(e.target.id==='download-activities') exportActivityCsv();
    if(e.target.id==='print-view') window.print();
    if(e.target.id==='refresh-data') {e.target.disabled=true;await api('/api/refresh','POST',{});await followRefresh();}
    if(e.target.id==='logout') {
      e.target.disabled=true;await api('/api/logout','POST',{});logoutChannel?.postMessage('logout');
      if('serviceWorker' in navigator) try{for(const registration of await navigator.serviceWorker.getRegistrations()) await registration.unregister();}catch{}
      lock();
    }
  } catch(error){if(D){message(error.message,true);if(e.target instanceof HTMLButtonElement)e.target.disabled=false;}}
});
document.addEventListener('submit',async e=>{
  const form=e.target;
  if(!['checkin-form','benchmark-form','questions-form'].includes(form.id)) return;
  e.preventDefault();
  const button=form.querySelector('button[type="submit"]');button.disabled=true;
  const status=form.querySelector('[role="status"]');if(status)status.textContent='Saving…';
  try {
    const value=Object.fromEntries(new FormData(form));
    if(form.id==='checkin-form') {
      const existing=checkins.find(x=>x.date===value.date);
      if(existing&&!confirm('Replace the saved check-in for '+value.date+'?')){if(status)status.textContent='';return;}
      for(const key of ['energy','legSoreness','anklePain','sleepQuality','jumpContacts','gymMinutes']) value[key]=value[key]===''?null:Number(value[key]);
      const saved=await api('/api/checkins','POST',{value,revision:existing?.revision||0});
      checkins=mergeById(checkins,[saved],'date');render();$('#checkin-status').textContent='Saved to your account.';
    } else if(form.id==='benchmark-form') {
      value.value=Number(value.value);value.id=crypto.randomUUID();
      const saved=await api('/api/benchmarks','POST',{value,revision:0});tests=mergeById(tests,[saved]);render();$('#benchmark-status').textContent='Saved to your account.';
    } else {
      const saved=await api('/api/answers','POST',{value,revision:answerRevision});answers=saved.answers;answerRevision=saved.revision;$('#answer-status').textContent='Saved to your account.';
    }
  } catch(error){if(status)status.textContent='Not saved: '+error.message;message(error.message,true);}
  finally{button.disabled=false;}
});
$('#include-races').addEventListener('change',e=>{S.races=e.target.checked;render();});
$('#close-dialog').onclick=()=>$('#detail-dialog').close();
$('#theme').onclick=()=>{document.body.classList.toggle('dark');$('#theme').textContent=document.body.classList.contains('dark')?'Light mode':'Dark mode';try{localStorage.setItem('training-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}};
try{if(localStorage.getItem('training-theme')==='dark'){$('body').classList.add('dark');$('#theme').textContent='Light mode';}}catch{}
let smallViewport=window.innerWidth<680;
window.addEventListener('resize',()=>{const small=window.innerWidth<680;if(small!==smallViewport){smallViewport=small;if(D&&['overview','recovery','progress'].includes(S.view))render();}});
window.addEventListener('pagehide',()=>{document.body.style.visibility='hidden';});
window.addEventListener('pageshow',event=>{if(event.persisted){document.body.style.visibility='hidden';api('/api/session').then(()=>location.reload()).catch(()=>lock());}else document.body.style.visibility='visible';});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&D) api('/api/session').catch(()=>{});});

async function start(){
  try {
    const session=await api('/api/session');csrf=session.csrf;setTimeout(lock,Math.max(0,Date.parse(session.expiresAt)-Date.now()));
    const [snapshotResult,status]=await Promise.all([api('/api/snapshot'),api('/api/status'),loadJournal()]);
    D=snapshotResult.snapshot;syncStatus=status;
    document.body.classList.remove('loading');
    if(!D){$('#heading-title').textContent='Your account is ready.';$('#heading-sub').textContent='Import the existing plan and snapshot using the setup command to open your dashboard.';$('#global-filters').classList.add('hide');return;}
    renderSyncControls();
    render();
    if(status.refreshing)followRefresh().catch(error=>message(error.message,true));
    if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{});
  }catch(error){document.body.classList.remove('loading');message('Unable to open your dashboard: '+error.message,true);}
}
start();
